-- auth 2 account_keys: One account per provider and account id, and per person where a provider links one.
do $check$
declare
  found text;
begin
  select string_agg(format('%s %s (accounts %s)', provider, subject, ids), '; ') into found
  from (
    select "provider_id" as provider, "account_id" as subject, string_agg(id::text, ', ' order by id) as ids
    from "auth"."account" group by "provider_id", "account_id" having count(*) > 1 order by 1, 2 limit 20
  ) as twice;
  if found is not null then
    raise exception 'The auth store has more than one account for a provider and account id: %. Keep one of each in a migration of the project''s own written before this one, then apply again.', found;
  end if;
end
$check$;

